package com.basiclab.iot.transform.runtime.service; import com.basiclab.iot.transform.core.domain.DlqRecord; import com.basiclab.iot.transform.runtime.dal.TransformRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class DlqService { private final TransformRepository repository; public DlqService(TransformRepository repository){this.repository=repository;} public Collection<DlqRecord> list(){return repository.listDlq();} public DlqRecord get(String id){return repository.dlq(id);} }